import { Queue, type JobsOptions } from 'bullmq';
import type { Redis } from 'ioredis';

/**
 * The queue contract between producers (equato-api, equato-webhooks) and the
 * workers (equato-scheduler). One definition, vendored into every backend.
 *
 * Every job carries a deterministic `jobId`, so enqueueing the same work twice
 * (a retried request, a duplicated webhook) is one job, not two. Workers are
 * idempotent on top of that — BullMQ is at-least-once.
 */
export const QueueName = {
  ANALYTICS_ROLLUP: 'analytics-rollup',
  SEARCH_REINDEX: 'search-reindex',
  NOTIFICATIONS: 'notifications',
  PRICE_ALERTS: 'price-alerts',
  MENU_SCAN: 'menu-scan',
  MEDIA_VARIANTS: 'media-variants',
  MAINTENANCE: 'maintenance',
  WEBHOOKS: 'webhooks',
  BILLING: 'billing',
  ANALYTICS_EVENTS: 'analytics-events',
} as const;
export type QueueName = (typeof QueueName)[keyof typeof QueueName];

export interface JobPayloads {
  'media-variants': { mediaId: string };
  'menu-scan': { scanJobId: string };
  /** One domain event from the transactional outbox (see outbox_events). */
  notifications: { outboxEventId: string };
  /** `id` is generated by the producer (UUIDv7) so a redelivered batch is deduplicated by the table key. */
  'analytics-events': { events: { id: string; type: string; businessId?: string | null; offeringId?: string | null; areaId?: string | null; sessionHash?: string | null; properties?: Record<string, unknown>; at: string }[] };
  webhooks: { webhookEventId: string };
  /** Subscription billing sweeps (scheduler only): renewals/trials/retries, reminders, reconciliation. */
  billing: { task: 'cycle' | 'reminders' | 'reconcile' };
  'analytics-rollup': { date?: string };
  'search-reindex': { businessId: string };
  'price-alerts': { offeringId: string };
  maintenance: { task: 'delete-objects'; bucket: string; keys: string[] } | { task: string };
}

/**
 * Finished jobs stay in Redis (which runs `noeviction`), so every tail is
 * bounded by count as well as age: during a database outage every job fails,
 * and an age-only limit kept them all for a week. Losing a failed-job record
 * loses no work — outbox-driven queues are re-queued by their sweeps.
 */
export const DEFAULT_JOB_OPTIONS: JobsOptions = {
  attempts: 5,
  backoff: { type: 'exponential', delay: 2_000 },
  removeOnComplete: { age: 3_600, count: 1_000 },
  removeOnFail: { age: 7 * 24 * 3_600, count: 5_000 },
};

/**
 * An analytics batch carries up to 500 events (≈200 KB): 1,000 completed ones
 * held ≈200 MB (measured, Phase 20). Once stored they are worthless in Redis.
 */
const QUEUE_JOB_OPTIONS: Partial<Record<QueueName, JobsOptions>> = {
  'analytics-events': { removeOnComplete: true, removeOnFail: { age: 24 * 3_600, count: 1_000 } },
};

export function jobOptionsFor(name: QueueName): JobsOptions {
  return { ...DEFAULT_JOB_OPTIONS, ...QUEUE_JOB_OPTIONS[name] };
}

export interface QueueProducer {
  add<N extends keyof JobPayloads>(queue: N, jobId: string, payload: JobPayloads[N], opts?: { delayMs?: number }): Promise<void>;
  close(): Promise<void>;
  /** False while the Redis connection is down (optional: test doubles may omit it). */
  isReady?(): boolean;
}

/**
 * Producer side. `connection` should be a DEDICATED ioredis connection
 * (BullMQ requires maxRetriesPerRequest: null on it); `queuePrefix` is the
 * keyspace's `<prefix>:queue`, the same one the workers consume.
 */
export function createQueueProducer(connection: Redis, queuePrefix: string): QueueProducer {
  const queues = new Map<string, Queue>();
  const q = (name: string) => {
    let queue = queues.get(name);
    if (!queue) {
      queue = new Queue(name, { connection, prefix: queuePrefix, defaultJobOptions: jobOptionsFor(name as QueueName) });
      queues.set(name, queue);
    }
    return queue;
  };
  return {
    async add(name, jobId, payload, opts = {}) {
      // BullMQ job ids may not contain ':' (it is the key separator).
      await q(name).add(name, payload, { jobId: jobId.replace(/:/g, '_'), ...(opts.delayMs ? { delay: opts.delayMs } : {}) });
    },
    async close() {
      await Promise.all([...queues.values()].map((x) => x.close()));
    },
    // With maxRetriesPerRequest: null, commands issued while Redis is down wait
    // in memory forever; best-effort producers check this first.
    isReady: () => connection.status === 'ready',
  };
}
